import tempfile
import torch
import torch.nn as nn
from topologies import Trainer, analysis, build, synth
root=tempfile.mkdtemp()
@synth.generator
def samples(ctx):
 features=torch.randn(4,generator=ctx.rng.torch)
 targets=torch.tensor([[0,1,3],[0,1,3],[0,2,3]])
 return {"inputs":synth.Tensor(features),"targets":synth.Tensor(targets)}
class CandidateLogits(nn.Module):
 def __init__(self):
  super().__init__()
  self.network=build("mlp","tiny",in_features=4,out_features=36)
 def forward(self,inputs):
  return {"logits":self.network(inputs).reshape(-1,3,3,4)}
dataset=synth.Spec("minimum-wer",generator=samples,size=8,splits={"train":1.0},seed=7,root=root,monitor="none").run()
train=dataset.for_recipe("structured-objective",split="train")
trainer=Trainer(CandidateLogits(),train,recipe="structured-objective",recipe_config={"loss":"minimum-wer","loss_kwargs":{"eos_token_id":3,"ignore_index":-100},"bindings":{"logits_or_prediction":{"output":"logits"},"targets":{"batch":"targets"}}},batch_size=4,max_epochs=1,device="cpu",logger="none",monitor="none")
result=trainer.fit()
summary=analysis.analyze(result,lambda values:{"global_step":values["global_step"]})
